CREATE COLUMN TABLE "TEST_AP"."OLGL" ("AbsEntry" INTEGER CS_INT NOT NULL , "SrcObjType" NVARCHAR(20) DEFAULT '-1' NOT NULL , "SrcObjAbs" INTEGER CS_INT DEFAULT -1 NOT NULL , "ObjType" NVARCHAR(20) DEFAULT '540000073', "UserSign" SMALLINT CS_INT, "PrintDate" LONGDATE CS_LONGDATE, "PrintTime" SMALLINT CS_INT, "PrBrand" NVARCHAR(30), "PrType" NVARCHAR(30), "PrModel" NVARCHAR(30), "PrFwVer" NVARCHAR(30), "PrDllVer" NVARCHAR(30), "FisSeries" NVARCHAR(30), "FisNumber" NVARCHAR(30), "DocNumber" NVARCHAR(30), "FisUser" SMALLINT CS_INT, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OLGL_SRC_DOC" ON "TEST_AP"."OLGL" ( "SrcObjType" ASC, "SrcObjAbs" ASC )